INSERT INTO builtin_question_edits (id,course,question_id,revision,data,previous_data,base_hash,action,note,actor,created_at) SELECT '9c9e4893-c498-4c49-a39e-9118ea5cb73e','os','os6-065',3,'{"id":"os6-065","category":"即時排程","type":"單選題","stem":"硬即時系統（Hard real-time systems）的關鍵特性是什麼？","options":["A. 提供排程的保證","B. 不保證排程時間","C. 任務可以被中斷","D. 任務必須在截止時間內完成"],"answer":"任務必須在截止期限前完成","translation":"Hard real-time systems require a task to be serviced by its ________. (Please answer in lowercase English.)","note":"","explanation":"硬即時系統的正確性同時取決於計算結果與完成時刻；工作錯過 deadline 即使之後算對，也不能算滿足原任務要求。\n\n設計時須估計最壞執行時間、阻塞與交接延遲，並驗證任務是否可排程。速度快或可被中斷，單獨都不等於能保證截止時間。","terms":[],"sourceType":"單選題","kindSource":"完整題庫提供題幹與選項","answerProvided":true,"sourceKey":"hard","sourceRecords":[13,269,14],"optionTranslations":["A. Scheduling guarantees are provided","B. Scheduling time is not guaranteed","C. Tasks can be interrupted","D. Tasks must complete by their deadlines"],"sourceExplanations":[{"sourceId":"community-65307e6c-1612-4c30-b48f-0489756453b5-49","text":"硬即時工作的正確性不只取決於算出的值，也取決於能否在 deadline 前完成。超過截止時間，即使最後算對，也可能已無法滿足系統需求。\n\n因此不能只讓工作在 deadline 前「開始」就算達成要求；還必須把所需 CPU 時間與可預期的阻塞、切換等延遲納入完成時間分析。"}],"aliases":["os6-064","硬即時系統（Hard real-time systems）要求任務必須在 ________ 內完成。（請用小寫英文回答）","硬即時系統(hard realtime syste,)的排程必須保證在 ____________ 時間內完成任務。（請用小寫英文回答）"],"images":[],"choiceKey":"D","imageKeys":[],"originalAnswer":"任務必須在截止期限前完成"}','{"id":"os6-065","category":"即時排程","type":"單選題","stem":"硬即時系統（Hard real-time systems）的關鍵特性是什麼？","options":["A. 提供排程的保證","B. 不保證排程時間","C. 任務可以被中斷","D. 任務必須在截止時間內完成"],"answer":"D","translation":"Hard real-time systems require a task to be serviced by its ________. (Please answer in lowercase English.)","note":"","explanation":"硬即時系統的正確性同時取決於計算結果與完成時刻；工作錯過 deadline 即使之後算對，也不能算滿足原任務要求。\n\n設計時須估計最壞執行時間、阻塞與交接延遲，並驗證任務是否可排程。速度快或可被中斷，單獨都不等於能保證截止時間。","terms":[],"sourceType":"單選題","kindSource":"完整題庫提供題幹與選項","answerProvided":true,"sourceKey":"hard","sourceRecords":[13,269,14],"optionTranslations":["A. Scheduling guarantees are provided","B. Scheduling time is not guaranteed","C. Tasks can be interrupted","D. Tasks must complete by their deadlines"],"sourceExplanations":[{"sourceId":"community-65307e6c-1612-4c30-b48f-0489756453b5-49","text":"硬即時工作的正確性不只取決於算出的值，也取決於能否在 deadline 前完成。超過截止時間，即使最後算對，也可能已無法滿足系統需求。\n\n因此不能只讓工作在 deadline 前「開始」就算達成要求；還必須把所需 CPU 時間與可預期的阻塞、切換等延遲納入完成時間分析。"}],"aliases":["os6-064","硬即時系統（Hard real-time systems）要求任務必須在 ________ 內完成。（請用小寫英文回答）","硬即時系統(hard realtime syste,)的排程必須保證在 ____________ 時間內完成任務。（請用小寫英文回答）"],"images":[],"choiceKey":"D","imageKeys":[],"originalAnswer":"任務必須在截止期限前完成"}','d79b6ed8612449e04c76e76a13b0cb3cd172bd99b5b1accb2df4ddc9d0165473','update','站主於 2026-11-26 確認答案；保留原答案歷史並同步答案對照與解析','owner-confirmed',1795704533111 WHERE (SELECT MAX(revision) FROM builtin_question_edits WHERE course='os' AND question_id='os6-065')=2 AND EXISTS (SELECT 1 FROM builtin_question_edits WHERE id='ba6cc15a-9da5-44d2-bf6c-bca670e2b1f6' AND data='{"id":"os6-065","category":"即時排程","type":"單選題","stem":"硬即時系統（Hard real-time systems）的關鍵特性是什麼？","options":["A. 提供排程的保證","B. 不保證排程時間","C. 任務可以被中斷","D. 任務必須在截止時間內完成"],"answer":"D","translation":"Hard real-time systems require a task to be serviced by its ________. (Please answer in lowercase English.)","note":"","explanation":"硬即時系統的正確性同時取決於計算結果與完成時刻；工作錯過 deadline 即使之後算對，也不能算滿足原任務要求。\n\n設計時須估計最壞執行時間、阻塞與交接延遲，並驗證任務是否可排程。速度快或可被中斷，單獨都不等於能保證截止時間。","terms":[],"sourceType":"單選題","kindSource":"完整題庫提供題幹與選項","answerProvided":true,"sourceKey":"hard","sourceRecords":[13,269,14],"optionTranslations":["A. Scheduling guarantees are provided","B. Scheduling time is not guaranteed","C. Tasks can be interrupted","D. Tasks must complete by their deadlines"],"sourceExplanations":[{"sourceId":"community-65307e6c-1612-4c30-b48f-0489756453b5-49","text":"硬即時工作的正確性不只取決於算出的值，也取決於能否在 deadline 前完成。超過截止時間，即使最後算對，也可能已無法滿足系統需求。\n\n因此不能只讓工作在 deadline 前「開始」就算達成要求；還必須把所需 CPU 時間與可預期的阻塞、切換等延遲納入完成時間分析。"}],"aliases":["os6-064","硬即時系統（Hard real-time systems）要求任務必須在 ________ 內完成。（請用小寫英文回答）","硬即時系統(hard realtime syste,)的排程必須保證在 ____________ 時間內完成任務。（請用小寫英文回答）"],"images":[],"choiceKey":"D","imageKeys":[],"originalAnswer":"任務必須在截止期限前完成"}');
INSERT INTO builtin_question_edits (id,course,question_id,revision,data,previous_data,base_hash,action,note,actor,created_at) SELECT '2de201f6-b6df-4f2f-988c-04eab4712b5e','algorithms','L6-047',3,'{"category":"計數排序","type":"填空題","q":"給定課本版本的COUNTING_SORT演算法。 COUNTING_SORT(A, B, k) 1 for i <- 1 to k 2 do c[i] <- 0 3 for j <- 1 to length[A] 4 do c[A[j]] <- c[A[j]] + 1 5 > c[i] now contains the number of elements equal to i 6 for i <- 2 to k 7 do c[i] <- c[i] + c[i-1] 8 > c[i] now contains the number of elements less than or equal to i 9 for j <- length[A] downto 1 10 do B[c[A[j]]] <- A[j] 11 c[A[j]] <- c[A[j]] - 1 A陣列的內容為 2,5,3,0,2,3,0,3 做到第9行 的 j = 2 時 B陣列的內容為何 ____________ 格式: 2,5,3,0,2,3,0,3 C陣列的內容為何 ____________ 格式: 2,5,3,0,2,3,0,3","a":"0,0,0,2,3,3,3,0 / 0,2,3,4,7,8","opts":[],"ex":"第 9 行 j=2 該輪開始時，已完成 j=8、7、6、5、4、3 的回填，尚未處理 A[2]=5 與 A[1]=2。\n\n累積計數原為 C[0..5]=2,2,4,7,7,8；依已處理的六個元素遞減後，C=0,2,3,4,7,8。B[1..8]=0,0,0,2,3,3,3,0；第 3、8 格尚未回填，依題目格式以 0 表示。\n\n本題答案已由站主於 2026-11-26 確認。","warn":false,"sources":["sorting-algorithms"],"answerProvided":true,"verified":true,"bookmarkId":"L6-047","sourceNumber":14,"appearances":["第三次第 14 題","補充試煉第 3 題"],"aliases":["給定課本版本的COUNTING_SORT演算法。\n\nCOUNTING_SORT(A, B, k)\n1  for i <- 1 to k\n2    do c[i] <- 0\n3  for j <- 1 to length[A]\n4    do c[A[j]] <- c[A[j]] + 1\n5  > c[i] now contains the number of elements equal to i\n6  for i <- 2 to k\n7    do c[i] <- c[i] + c[i-1]\n8  > c[i] now contains the number of elements less than or equal to i\n9  for j <- length[A] downto 1\n10   do B[c[A[j]]] <- A[j]\n11      c[A[j]] <- c[A[j]] - 1\n\nA陣列的內容為 2,5,3,0,2,3,0,3 做到第9行 的 j = 2 時 B陣列的內容為何[__1__] 格式: 2,5,3,0,2,3,0,3 C陣列的內容為何[__2__] 格式: 2,5,3,0,2,3,0,3"],"sourceExplanations":[{"sourceId":"L6-047-original-review-20261026","text":"內容校對前原始文字；修正排版、抄錄或 0 鍵值程式範圍，保留供原題查詢。"}],"stem":"給定課本版本的COUNTING_SORT演算法。 COUNTING_SORT(A, B, k) 1 for i <- 1 to k 2 do c[i] <- 0 3 for j <- 1 to length[A] 4 do c[A[j]] <- c[A[j]] + 1 5 > c[i] now contains the number of elements equal to i 6 for i <- 2 to k 7 do c[i] <- c[i] + c[i-1] 8 > c[i] now contains the number of elements less than or equal to i 9 for j <- length[A] downto 1 10 do B[c[A[j]]] <- A[j] 11 c[A[j]] <- c[A[j]] - 1 A陣列的內容為 2,5,3,0,2,3,0,3 做到第9行 的 j = 2 時 B陣列的內容為何 ____________ 格式: 2,5,3,0,2,3,0,3 C陣列的內容為何 ____________ 格式: 2,5,3,0,2,3,0,3","options":[],"answer":"0,0,0,2,3,3,3,0 / 0,2,3,4,7,8","explanation":"第 9 行 j=2 該輪開始時，已完成 j=8、7、6、5、4、3 的回填，尚未處理 A[2]=5 與 A[1]=2。\n\n累積計數原為 C[0..5]=2,2,4,7,7,8；依已處理的六個元素遞減後，C=0,2,3,4,7,8。B[1..8]=0,0,0,2,3,3,3,0；第 3、8 格尚未回填，依題目格式以 0 表示。\n\n本題答案已由站主於 2026-11-26 確認。","images":[],"translation":"","optionTranslations":[],"note":"","imageKeys":[],"originalAnswer":"0,0,2,3,3,3,3,0 / 0,2,3,4,7,7"}','{"category":"計數排序","type":"填空題","q":"給定課本版本的COUNTING_SORT演算法。 COUNTING_SORT(A, B, k) 1 for i <- 1 to k 2 do c[i] <- 0 3 for j <- 1 to length[A] 4 do c[A[j]] <- c[A[j]] + 1 5 > c[i] now contains the number of elements equal to i 6 for i <- 2 to k 7 do c[i] <- c[i] + c[i-1] 8 > c[i] now contains the number of elements less than or equal to i 9 for j <- length[A] downto 1 10 do B[c[A[j]]] <- A[j] 11 c[A[j]] <- c[A[j]] - 1 A陣列的內容為 2,5,3,0,2,3,0,3 做到第9行 的 j = 2 時 B陣列的內容為何 ____________ 格式: 2,5,3,0,2,3,0,3 C陣列的內容為何 ____________ 格式: 2,5,3,0,2,3,0,3","a":"0,0,0,2,3,3,3,0/0,2,3,4,7,8","opts":[],"ex":"","warn":false,"sources":["sorting-algorithms"],"answerProvided":true,"verified":true,"bookmarkId":"L6-047","sourceNumber":14,"appearances":["第三次第 14 題","補充試煉第 3 題"],"aliases":["給定課本版本的COUNTING_SORT演算法。\n\nCOUNTING_SORT(A, B, k)\n1  for i <- 1 to k\n2    do c[i] <- 0\n3  for j <- 1 to length[A]\n4    do c[A[j]] <- c[A[j]] + 1\n5  > c[i] now contains the number of elements equal to i\n6  for i <- 2 to k\n7    do c[i] <- c[i] + c[i-1]\n8  > c[i] now contains the number of elements less than or equal to i\n9  for j <- length[A] downto 1\n10   do B[c[A[j]]] <- A[j]\n11      c[A[j]] <- c[A[j]] - 1\n\nA陣列的內容為 2,5,3,0,2,3,0,3 做到第9行 的 j = 2 時 B陣列的內容為何[__1__] 格式: 2,5